using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() returned metadata for: {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// With the default resolver every type is resolvable, so Person succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? personInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Person>() succeeded – type: {personInfo!.Type.Name}");
}

// Build options whose resolver only knows about Person, not about int[]:
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers =
        {
            ti =>
            {
                if (ti.Type == typeof(int[]))
                    throw new NotSupportedException("int[] not supported");
            }
        }
    }
};

if (limited.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
{
    Console.WriteLine($"TryGetTypeInfo<int[]>() succeeded – type: {arrayInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int[]>() returned false – metadata not available (no exception thrown)");
}

// --- record used above ---
public record Person(string Name, int Age);

